import React from "react";
import {
  Document,
  Packer,
  Paragraph,
  Table,
  TableRow,
  TableCell,
  WidthType,
  AlignmentType,
  TextRun,
} from "docx";

const FuelReport = () => {

  const generateDoc = async () => {

    const data = [
      ["১", "গাড়ি-১", "১০ লিটার"],
      ["২", "গাড়ি-২", "১৫ লিটার"],
    ];

    const tableRows = data.map((row) =>
      new TableRow({
        children: row.map(
          (cell) =>
            new TableCell({
              width: { size: 33, type: WidthType.PERCENTAGE },
              children: [
                new Paragraph({
                  children: [
                    new TextRun({
                      text: cell,
                      size: 24,
                      color: "000000",
                    }),
                  ],
                  alignment: AlignmentType.CENTER,
                }),
              ],
            })
        ),
      })
    );

    const doc = new Document({
      sections: [
        {
          children: [

            // Title
            new Paragraph({
              children: [
                new TextRun({
                  text: "জ্বালানি প্রতিবেদন",
                  bold: true,
                  size: 32,
                }),
              ],
              alignment: AlignmentType.CENTER,
              spacing: { after: 300 },
            }),

            // Table
            new Table({
              width: {
                size: 100,
                type: WidthType.PERCENTAGE,
              },
              rows: [
                new TableRow({
                  children: ["ক্রমিক", "গাড়ির নাম", "জ্বালানি"]
                    .map(
                      (head) =>
                        new TableCell({
                          children: [
                            new Paragraph({
                              children: [
                                new TextRun({
                                  text: head,
                                  bold: true,
                                  size: 26,
                                }),
                              ],
                              alignment: AlignmentType.CENTER,
                            }),
                          ],
                        })
                    ),
                }),

                ...tableRows,
              ],
            }),

            // Space
            new Paragraph({ text: "", spacing: { after: 400 } }),

            // Signature Section
            new Paragraph({
              children: [
                new TextRun({
                  text: "স্বাক্ষরিত",
                  bold: true,
                  size: 24,
                }),
              ],
              alignment: AlignmentType.RIGHT,
              spacing: { before: 400, after: 40 },
            }),

            new Paragraph({
              children: [
                new TextRun({
                  text: "উপজেলা নির্বাহী অফিসার",
                  size: 24,
                }),
              ],
              alignment: AlignmentType.RIGHT,
              spacing: { after: 20 },
            }),

            new Paragraph({
              children: [
                new TextRun({
                  text: "জীবননগর, চুয়াডাঙ্গা।",
                  size: 24,
                }),
              ],
              alignment: AlignmentType.RIGHT,
            }),
          ],
        },
      ],
    });

    const blob = await Packer.toBlob(doc);

    const url = window.URL.createObjectURL(blob);

    // FIXED DOWNLOAD
    const a = document.createElement("a");
    a.href = url;
    a.download = "fuel_report.docx";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <div style={{ padding: "20px" }}>
      <button onClick={generateDoc}>
        Download Report
      </button>
    </div>
  );
};

export default FuelReport;
